import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives as _primitives } from '@/primitives';
import { text as _text } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // ---- Plane ----
  const geometry = new ctx.THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
  });
  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  // Load texture (synchronous entry, async load)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 39,
      color: (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2',
      align: 'center',
    });
    // Position text just above the plane to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // ---- Cinematic Primitives ----
  const activePrimitives = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const instance = ctx.primitives[prim.name](group, prim.params);
    activePrimitives.push(instance);
  }

  // ---- Handlers placeholder ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();

    // Cleanup primitives
    for (const p of activePrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return group;
}
